def f(inp):
    g=[r[:] for r in inp]; H=len(g);W=len(g[0])
    cells=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==5]
    r0=min(i for i,j in cells); r1=max(i for i,j in cells)
    c0=min(j for i,j in cells); c1=max(j for i,j in cells)
    seeds={}
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (0,5):
                bi=(0 if i<r0 else 2); bj=(0 if j<c0 else 2)
                seeds.setdefault((bi,bj),[]).append((g[i][j], abs(i-r0/3)+abs(j-c0/3)))
    # assign each block: try own seed first; else diagonal mirror seed
    out=[[0]*W for _ in range(H)]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            block=( (0 if i<(r0+r1)//2 else 1),(0 if j<(c0+c1)//2 else 1) )
            v = None
            for seedv,_ in seeds.get(block,[]): v = seedv; break
            if v is None and len(seeds)==2:
                m = (1-block[0], 1-block[1])
                for seedv,_ in seeds.get(m,[]): v = seedv; break
            if v is None: continue
            out[i][j]=v
    return out
